// REACT-01 渲染、组件纯度与 state snapshot
// 首考题 3 原文：使用中文讲义“建立可复现的练习工程”和“用手动释放回调固定观察顺序”的完整源码，初始 count=0，每组刷新。运行表格五组操作并编写组件测试，逐步交付输入、入队过程、output 和 callback snapshot；预期值式单次=1、函数单次=3、三次独立点击=1/2/3、预约后先加三再释放的值式=3/1/1、函数式=3/4/5；保存分阶段日志，不按固定 render 次数判断；运行纯度反例并验证输入是否被污染
// 首考题 4 原文：固定失败为预约值式后先加三，再释放导致计数回到 1。仅比较“旧快照替换”“函数更新累积”“重复用户事件”三个候选，提交最小复现、逐项证伪和改为函数更新后的 3/4/5 回归；另以纯度片段的 push 反例验证修复前后输入和输出，不能依赖 Date.now 两次不同
// 把题目给定的具体 fixture 写入 fixedInput；不要把预期替换成通用 PASS/CONTROLLED。
const fixedInput = Object.freeze({ /* 填写首考题 3 的固定输入 */ });
const expected = Object.freeze({ /* 填写题目要求的具体预期 */ });

function solve(input) {
  // 根据学习资料实现首考题 3。
  throw new Error('TODO');
}

let actual;
try {
  actual = solve(fixedInput);
  console.log({ fixedInput, expected, actual });
  console.assert(JSON.stringify(actual) === JSON.stringify(expected), '实际输出与首考题 3 的具体预期不一致');
} catch (error) {
  console.error({ fixedInput, expected, error: String(error) });
  throw error;
}

